```javascript
const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

rl.on('line', (line) => {
    const s = line;
    const chars = s.split('');
    const size = chars.length;
    const middle = Math.floor((size - 1) / 2);

    const odd = size % 2 !== 0;

    let j = size - 1;
    let i = 0;
    let counter = 1;

    let palindrom = true;
    while (true) {
        const begin = chars[i];
        const end = chars[j];
        if (begin !== end) {
            if (counter === 0) {
                palindrom = false;
                break;
            }
            counter--;
        }
        if (i === middle) {
            break;
        }
        i++;
        j--;
    }

    if ((palindrom && counter === 0) || (palindrom && counter === 1 && odd)) {
        console.log("YES");
    } else {
        console.log("NO");
    }

    rl.close();
});
```

